import base64
import PyInstaller.__main__
import os
import shutil

exe_file_name = input("Enter Your Exe File Name EX: APP without exe .. :")


def base64_image():
    return b''


directory = os.getcwd()
exe_folder = os.path.expanduser("~/Desktop/exe_folder/")
if not os.path.exists(exe_folder):
    os.mkdir(exe_folder)
temp = rf'{directory}/.temp'
if not os.path.exists(temp):
    os.mkdir(temp)
icon_file_name = rf'{temp}/nobody.ico'
with open(icon_file_name, 'wb') as img:
    img.write(base64.decodebytes(base64_image()))
img.close()


def create_exe_app(filename):
    try:
        PyInstaller.__main__.run(
            [
                f'{filename}',
                '--noconfirm',
                f'-n={exe_file_name.strip()}',
                f'-i={icon_file_name}',
                '-F',
                '-y',
                '-c',
                # '--hidden-import=bs4',
                f'--specpath={temp}',
                f'--distpath={exe_folder}',
                '--noupx',
                f'--workpath={temp}',
                '--log-level=WARN',
                '--clean',
            ]
        )
        print(rf"Your File is ready to use ...{exe_folder}/{exe_file_name}.exe")
    except Exception as e:
        print(e)


create_exe_app('Run.py')
shutil.rmtree(temp)
